INSERT INTO public.salt_master VALUES ('1f7e59d5-bcff-4914-8853-99bd5d866316', 'Terbinafine', 'Antifungal', '2026-06-12 13:54:49.006104+00');
INSERT INTO public.drug_interaction VALUES ('67512d0c-eef7-4ba8-8459-cc7ad766c3dd', 'b92437fe-4f75-44ed-a16d-0640e5539b56', '48649021-d9bb-42b3-9b91-838292c5b5a7', 'MODERATE', 'Concurrent use of Aspirin and Ibuprofen may reduce the cardioprotective effect of Aspirin and increase risk of gastrointestinal bleeding.', 'Avoid regular combined use. If both are needed, take Aspirin 30 minutes before Ibuprofen. Advise patient to report GI symptoms.', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('e6327986-4517-41ce-9b01-59ea921774aa', '8ce85afb-a363-471e-b87e-ff26f80a26f9', '8974cddb-e973-4784-a389-7fa3e43592f4', 'MODERATE', 'Furosemide can increase Metformin plasma levels by reducing renal clearance, raising the risk of lactic acidosis.', 'Monitor renal function when combining. Consider dose adjustment of Metformin. Hold Metformin if eGFR drops below 30.', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('7fd0b54c-04ee-4807-8283-d8f22bc2717a', '8ce85afb-a363-471e-b87e-ff26f80a26f9', 'c15dceca-fcb7-4663-892d-d8f2dee93b51', 'MODERATE', 'Hydrochlorothiazide can cause hyperglycemia, reducing the efficacy of Metformin in controlling blood glucose.', 'Monitor blood glucose closely when initiating or changing thiazide dose. Adjust antidiabetic therapy as needed.', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('06519e7a-c824-4c30-98c7-9507af75903d', 'b92437fe-4f75-44ed-a16d-0640e5539b56', 'fc16f785-a3dd-4e15-90f9-ab7bca43215c', 'HIGH', 'Combined use of Aspirin and Diclofenac significantly increases the risk of gastrointestinal ulceration and bleeding.', 'Avoid co-administration unless under specialist supervision. If unavoidable, add a PPI (e.g. Omeprazole) for gastric protection.', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('15d0ac46-de8d-4fe8-a7f3-41c47bf4a099', 'cd442336-90b2-410b-afcb-e3c770a9c4cf', '2bdffbda-52a1-41ee-9e79-0dc22767d809', 'HIGH', 'Erythromycin inhibits CYP3A4, significantly increasing Atorvastatin plasma levels and the risk of myopathy or rhabdomyolysis.', 'Temporarily suspend Atorvastatin during short Erythromycin courses. If statin therapy cannot be interrupted, consider a non-CYP3A4 metabolised statin (e.g. Rosuvastatin).', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('6e9fe5c9-5179-4a31-a822-44cd95290d5a', 'cd442336-90b2-410b-afcb-e3c770a9c4cf', 'b699bf7a-97a5-4481-acc9-17be437369ea', 'CRITICAL', 'Itraconazole is a potent CYP3A4 inhibitor that can dramatically increase Atorvastatin levels, causing severe myopathy or rhabdomyolysis.', 'Avoid co-administration. Suspend Atorvastatin during Itraconazole treatment. Use Fluconazole (weaker CYP3A4 effect) as antifungal alternative where possible.', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('4323304c-e5ee-4a5e-8125-10ed73701bed', 'dd6d8966-2e6c-4395-ad7c-25a5b45e0aac', '7cc67f16-498d-4b3a-9167-17b3be171a9a', 'HIGH', 'Ciprofloxacin inhibits CYP1A2, reducing Theophylline clearance and increasing risk of theophylline toxicity (nausea, tremors, seizures).', 'Reduce Theophylline dose by 30–50% when starting Ciprofloxacin. Monitor serum theophylline levels and clinical signs of toxicity.', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('be551f5d-6d2e-4c98-98d4-d8ca39cb85da', 'a6f3d4a7-fed8-4f67-a336-1ed35f479494', '0e33b805-9974-4e95-a92c-065d204c55b4', 'MODERATE', 'Concurrent use of Fluconazole and Metronidazole may potentiate QT prolongation and increase risk of serious cardiac arrhythmias.', 'Use with caution in patients with cardiac risk factors. Obtain baseline ECG and monitor for QT prolongation.', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('631e0935-c7d5-4b5b-b0c1-bab0b430f7f7', '52fd107d-16a8-4914-9241-b35292a20ab5', '48649021-d9bb-42b3-9b91-838292c5b5a7', 'HIGH', 'Prednisolone combined with Ibuprofen substantially increases the risk of gastrointestinal ulceration, bleeding, and perforation.', 'Avoid combination where possible. If both required, add a PPI (Omeprazole 20mg daily) for gastric protection. Warn patient to report abdominal pain or black stools immediately.', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('01cc9428-09bb-440f-9f04-5aee9f633a89', '7937d0d8-8a66-4cf7-aaf5-c96be1bae616', '70d97e21-010a-48b1-bba1-348ad2e05208', 'HIGH', 'Combining Sertraline with Tramadol significantly raises the risk of serotonin syndrome (agitation, hyperthermia, tachycardia, clonus).', 'Avoid co-administration if possible. If both are prescribed, use the lowest effective Tramadol dose and monitor closely for serotonin syndrome symptoms for 24 hours after initiation.', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('5b83658a-fa43-43f1-93bf-9b140cb25c0a', '2bf67fc2-ec6a-4f08-9179-1a1924bd1c61', '2bdffbda-52a1-41ee-9e79-0dc22767d809', 'HIGH', 'Erythromycin inhibits the metabolism of Carbamazepine, leading to elevated plasma levels and risk of carbamazepine toxicity (diplopia, ataxia, vomiting).', 'Avoid combination. If Erythromycin is required in a patient on Carbamazepine, consider an alternative antibiotic such as Azithromycin with less CYP3A4 interaction.', true, '2026-06-12 13:54:49.036342+00');
INSERT INTO public.drug_interaction VALUES ('000a252e-a3ce-475e-8d32-922774a72fe1', '8ce85afb-a363-471e-b87e-ff26f80a26f9', '8612b77c-89b0-41fb-95cc-b5f79a5f0f72', 'LOW', 'Combined use of Metformin and Dapagliflozin is a standard antidiabetic regimen but requires monitoring for volume depletion and urinary tract infections.', 'Ensure adequate hydration. Monitor renal function periodically. Educate patient on signs of dehydration and UTI.', true, '2026-06-12 13:54:49.036342+00');
